/bin/bash -lc "node <<'NODE'
const fs = require('node:fs');
const {execFileSync} = require('node:child_process');
const stamp = execFileSync('date',['-u','+%FT%TZ'],{encoding:'utf8'}).trim();
fs.appendFileSync('DIARY.md', '\\n## '+stamp+' — day-two reading replay\\n\\nScope is discovery only. Began with "'`npx snapback4 init --adapt --day2` without `--apply`; it printed the handover and then refused frozen-client dependency resolution because playwright-core is absent. Followed the rename, old-client compatibility, proof API digest, and persistent production roster documentation. Read the three PREVIOUS handover files. The manifest pins 0.4.43 but the installed package reports 0.4.44; a schema-only check passed under 0.4.44. No production release exists at ./deploy. No packages were installed, app built, users provisioned, servers started, or full proofs run. DAY2-PLAN.md records exact future commands, a single stored charge rename with an owner-only update constraint, explicit frozen-v1 result wrappers, complete persistent-data comparisons, rollback/forward previews, and unresolved zero-value/target-version/adoption limits.'"\\n\\n### React web discovery\\n\\nThe inherited React hooks and public VITE_SNAPBACK_URL setting can be retained. Planned UI work is charge wording and creation input plus an owner charge-edit form. Existing Playwright already reads CHROME and uses --no-sandbox; frontend dependencies and CHROME are unavailable in this discovery environment, so no browser result is claimed.\\n');
const t = Math.floor(Date.now()/1000);
const entries = [
 {t,area:'install',kind:'environment',severity:2,minutes_lost:0,summary:'Day-two preview stops on absent inherited frontend dependency',detail:'npx snapback4 init --adapt --day2 printed its handover then exited 2: frozen client dependency resolution: Cannot find package playwright-core imported from scripts/frontend-proof.mjs. TypeScript and Vite package manifests are also absent.',workaround:'Read the printed handover and recommended documentation; recorded dependency restoration as a future implementation step. No installation in reading scope.',suggested_fix:'Allow handover/preview discovery to finish with a clearly separated nonfatal dependency readiness warning.'},
 {t,area:'upgrade',kind:'environment',severity:2,minutes_lost:0,summary:'Installed CLI differs from exact package manifest pin',detail:'package.json specifies snapback4 0.4.43, while installed node_modules/snapback4/package.json reports 0.4.44. The allowed schema check passed using 0.4.44, so it does not validate the required target runtime.',workaround:'Recorded exact-version restoration and target-version documentation recheck in DAY2-PLAN.md; did not change packages.',suggested_fix:'Report installed and requested versions together in the handover before presenting version-dependent commands.'}
];
for (const entry of entries) fs.appendFileSync('friction.jsonl',JSON.stringify(entry)+'\\n');
const plan = fs.readFileSync('DAY2-PLAN.md','utf8');
console.log(JSON.stringify({plan:'DAY2-PLAN.md',lines:plan.split('\\n').length,hasReleaseCommands:plan.includes('rollback ./deploy'),hasFrozenClient:plan.includes('npm --prefix v1 run client:calls'),hasProductionRoster:plan.includes('deploy/proof-accounts/default.json'),hasUnresolvedLimits:plan.includes('## Unresolved limits'),diaryUpdated:true,frictionEntriesAdded:entries.length}));
NODE"
